-- The TARGET is these definitions, which also appear in the context: D11, D12, d13
def D11 (N : S1 X Y) : Prop :=
  Nonempty N.A1 ∧ ∀ m n, Relation.TransGen N.D8 m n

def D12 (N : S1 X Y) : Prop :=
  ∀ m n, m ≠ n → ¬ (Relation.TransGen N.D8 m n ∧ Relation.TransGen N.D8 n m)

def d13 (N : S1 X Y) : ℕ := Fintype.card N.A1

